import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"20、【观】 坤下巽上","description":"温公易说 - 20、【观】 坤下巽上","frontmatter":{"title":"20、【观】 坤下巽上","description":"温公易说 - 20、【观】 坤下巽上"},"headers":[],"relativePath":"zh/classics/wengong/021.md","filePath":"zh/classics/wengong/021.md"}'),n={name:"zh/classics/wengong/021.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_20、【观】-坤下巽上" tabindex="-1">20、【观】 坤下巽上 <a class="header-anchor" href="#_20、【观】-坤下巽上" aria-label="Permalink to “20、【观】 坤下巽上”">​</a></h1><h3 id="彖曰-大观在上-顺而巽-中正以观天下。观盥而不荐-有孚颙若-下观而化也。观天之神道-而四时不忒。圣人以神道设教-而天下服矣。" tabindex="-1">彖曰：大观在上，顺而巽，中正以观天下。观盥而不荐，有孚颙若，下观而化也。观天之神道，而四时不忒。圣人以神道设教，而天下服矣。 <a class="header-anchor" href="#彖曰-大观在上-顺而巽-中正以观天下。观盥而不荐-有孚颙若-下观而化也。观天之神道-而四时不忒。圣人以神道设教-而天下服矣。" aria-label="Permalink to “彖曰：大观在上，顺而巽，中正以观天下。观盥而不荐，有孚颙若，下观而化也。观天之神道，而四时不忒。圣人以神道设教，而天下服矣。”">​</a></h3><p>观者，上以德示人，使人观而化之也。盥圭洁其德也，荐丰备其物也。颙，人君有德之容也。夫德由内出，物自外至。苟内德不充，虽外物丰备，不能化人也。故黍稷非馨，明德惟馨。苟有明信，涧溪沼沚之毛，苹蘩薀藻之菜，可荐于鬼神，可羞于王公，而况下民乎？故曰盥而不荐。君人者，能隆内杀外，勤本略末，德洁诚着，物皆信之，然后可以不为而成，不言而化。恭已南面，颙然而已，所谓神道设教，而天下服也。故曰有孚颙若。</p><h3 id="象曰-风行地上-观。先王以省方-观民设教。" tabindex="-1">象曰：风行地上，观。先王以省方，观民设教。 <a class="header-anchor" href="#象曰-风行地上-观。先王以省方-观民设教。" aria-label="Permalink to “象曰：风行地上，观。先王以省方，观民设教。”">​</a></h3><p>先王省方，考礼乐，恊时日，饬法度，以示人为观之象。</p><h3 id="初六-童观-小人无咎-君子吝-象曰-初六童观-小人道也。" tabindex="-1">初六：童观，小人无咎，君子吝 象曰：初六童观，小人道也。 <a class="header-anchor" href="#初六-童观-小人无咎-君子吝-象曰-初六童观-小人道也。" aria-label="Permalink to “初六：童观，小人无咎，君子吝 象曰：初六童观，小人道也。”">​</a></h3><h3 id="六二-窥观-利女贞-象曰-窥观女贞-亦可丑也。" tabindex="-1">六二：窥观，利女贞 象曰：窥观女贞，亦可丑也。 <a class="header-anchor" href="#六二-窥观-利女贞-象曰-窥观女贞-亦可丑也。" aria-label="Permalink to “六二：窥观，利女贞 象曰：窥观女贞，亦可丑也。”">​</a></h3><h3 id="六三-观我生-进退-象曰-观我生进退-未失道也。" tabindex="-1">六三：观我生，进退 象曰：观我生进退，未失道也。 <a class="header-anchor" href="#六三-观我生-进退-象曰-观我生进退-未失道也。" aria-label="Permalink to “六三：观我生，进退 象曰：观我生进退，未失道也。”">​</a></h3><h3 id="六四-观国之光-利用宾于王-象曰-观国之光-尚宾也。" tabindex="-1">六四：观国之光，利用宾于王 象曰：观国之光，尚宾也。 <a class="header-anchor" href="#六四-观国之光-利用宾于王-象曰-观国之光-尚宾也。" aria-label="Permalink to “六四：观国之光，利用宾于王 象曰：观国之光，尚宾也。”">​</a></h3><h3 id="九五-观我生-君子无咎-象曰-观我生-观民也。" tabindex="-1">九五：观我生，君子无咎 象曰：观我生，观民也。 <a class="header-anchor" href="#九五-观我生-君子无咎-象曰-观我生-观民也。" aria-label="Permalink to “九五：观我生，君子无咎 象曰：观我生，观民也。”">​</a></h3><h3 id="上九-观其生-君子无咎-象曰-观其生-志未平也。" tabindex="-1">上九：观其生，君子无咎 象曰：观其生，志未平也。 <a class="header-anchor" href="#上九-观其生-君子无咎-象曰-观其生-志未平也。" aria-label="Permalink to “上九：观其生，君子无咎 象曰：观其生，志未平也。”">​</a></h3>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
